B.adl=new A.jJ("fleas",B.uP,"Fleas","\u0627\u0644\u0628\u0631\u0627\u063a\u064a\u062b",B.hM,"Small jumping insects that cause itching. They can cause anaemia in young pets and pass on tapeworm.","\u062d\u0634\u0631\u0627\u062a \u0635\u063a\u064a\u0631\u0629 \u0642\u0627\u0641\u0632\u0629 \u062a\u0633\u0628\u0651\u0628 \u0627\u0644\u062d\u0643\u0651\u0629\u060c \u0648\u0642\u062f \u062a\u0633\u0628\u0651\u0628 \u0641\u0642\u0631 \u0627\u0644\u062f\u0645 \u0644\u0644\u062d\u064a\u0648\u0627\u0646\u0627\u062a \u0627\u0644\u0635\u063a\u064a\u0631\u0629\u060c \u0648\u062a\u0646\u0642\u0644 \u0627\u0644\u062f\u0648\u062f\u0629 \u0627\u0644\u0634\u0631\u064a\u0637\u064a\u0629.",B.cB,B.cB,B.agD)
B.bdv=s(["A tick stuck to the skin, often around the ears, neck or between the toes.","Fever, weakness and loss of appetite.","Pale gums, a bleeding nose, or red or dark urine: go to the vet now."],t.s)
B.b12=s(["\u0642\u064f\u0631\u0627\u062f\u0629 \u0645\u0644\u062a\u0635\u0642\u0629 \u0628\u0627\u0644\u062c\u0644\u062f\u060c \u063a\u0627\u0644\u0628\u064b\u0627 \u062d\u0648\u0644 \u0627\u0644\u0623\u0630\u0646\u064a\u0646 \u0623\u0648 \u0627\u0644\u0631\u0642\u0628\u0629 \u0623\u0648 \u0628\u064a\u0646 \u0627\u0644\u0623\u0635\u0627\u0628\u0639.","\u062d\u0645\u0651\u0649 \u0648\u0636\u0639\u0641 \u0648\u0642\u0644\u0629 \u0641\u064a \u0627\u0644\u0623\u0643\u0644.","\u0644\u062b\u0629 \u0634\u0627\u062d\u0628\u0629\u060c \u0623\u0648 \u0646\u0632\u064a\u0641 \u0645\u0646 \u0627\u0644\u0623\u0646\u0641\u060c \u0623\u0648 \u0628\u0648\u0644 \u0623\u062d\u0645\u0631 \u0623\u0648 \u062f\u0627\u0643\u0646: \u062a\u0648\u062c\u0651\u0647 \u0625\u0644\u0649 \u0627\u0644\u0637\u0628\u064a\u0628 \u0627\u0644\u0628\u064a\u0637\u0631\u064a \u0641\u0648\u0631\u064b\u0627."],t.s)
B.adb=new A.fU(B.ie,B.bdv,B.b12)
B.b9T=s(["Remove the tick with a tick tool: grip close to the skin and pull out steadily.","Do not squeeze, burn or put oil on it. Clean the spot and wash your hands.","If your pet seems ill after a tick, see a vet today; a blood test shows tick fever."],t.s)
B.aFH=s(["\u0623\u0632\u0644 \u0627\u0644\u0642\u064f\u0631\u0627\u062f\u0629 \u0628\u0623\u062f\u0627\u0629 \u062e\u0627\u0635\u0629: \u0623\u0645\u0633\u0643\u0647\u0627 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u0627\u0644\u062c\u0644\u062f \u0648\u0627\u0633\u062d\u0628\u0647\u0627 \u0628\u062b\u0628\u0627\u062a.","\u0644\u0627 \u062a\u0639\u0635\u0631\u0647\u0627 \u0648\u0644\u0627 \u062a\u062d\u0631\u0642\u0647\u0627 \u0648\u0644\u0627 \u062a\u0636\u0639 \u0639\u0644\u064a\u0647\u0627 \u0632\u064a\u062a\u064b\u0627. \u0646\u0638\u0651\u0641 \u0627\u0644\u0645\u0643\u0627\u0646 \u0648\u0627\u063a\u0633\u0644 \u064a\u062f\u064a\u0643.","\u0625\u0630\u0627 \u0628\u062f\u0627 \u062d\u064a\u0648\u0627\u0646\u0643 \u0645\u0631\u064a\u0636\u064b\u0627 \u0628\u0639\u062f \u0627\u0644\u062a\u0639\u0631\u0651\u0636 \u0644\u0644\u0642\u0631\u0627\u062f\u060c \u0641\u0631\u0627\u062c\u0639 \u0627\u0644\u0637\u0628\u064a\u0628 \u0627\u0644\u064a\u0648\u0645\u061b \u0641\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062f\u0645 \u064a\u0643\u0634\u0641 \u062d\u0645\u0651\u0649 \u0627\u0644\u0642\u0631\u0627\u062f."],t.s)
